List<String> collect(TrieNode n, String path) {
  final out = <String>[];
  if (n.isWord) out.add(path);
  final keys = n.children.keys.toList()..sort();
  for (final k in keys) {
    out.addAll(collect(n.children[k]!, path + k));
  }
  return out;
}

