String shortestRoot(Trie t, String word) {
  var n = t.root;
  for (var i = 0; i < word.length; i++) {
    final next = n.children[word[i]];
    if (next == null) return word;
    n = next;
    if (n.isWord) return word.substring(0, i + 1);
  }
  return word;
}

